	if not check("btn", play_button != null, "Nel menu serve il nodo PlayButton"):
		return
	click_button(play_button)
	await wait_frames(3)
	check("questions_loaded", QuizData.questions.size() >= 2, "Premendo Gioca, QuizData.questions deve contenere le domande della risorsa (trovate: %d)" % QuizData.questions.size())

